// Fallback used if a row's Category doesn't match anything above (e.g. blank or a genuine typo
// that normalization below can't fix). Set to a real category name to enable a fallback instead
// of erroring, or leave null to fail loudly.
// const DEFAULT_CATEGORY = null;

// Matches regardless of case and regardless of spacing differences, e.g.
// "LOG-Warehouse", "LOG- Warehouse", "log -warehouse" all resolve to the same entry.
// It does NOT fix genuine misspellings -- those still need either a sheet correction
// or DEFAULT_CATEGORY above.
const normalizeKey = (s) =>
  (s || "").toString().trim().toLowerCase().replace(/\s+/g, "");

const NORMALIZED_MAP = {};
for (const [key, value] of Object.entries(CONTENT_MAP)) {
  NORMALIZED_MAP[normalizeKey(key)] = value;
}

const results = [];
for (const item of $input.all()) {
  const d = item.json;
  const rawCategory = d["Category"] || "";
  const stage = d["nextFollowUp"];

  const templatesForCategory = NORMALIZED_MAP[normalizeKey(rawCategory)];
  if (!templatesForCategory) {
    throw new Error(
      `No follow-up content found for Category "${rawCategory}" (row: ${d["Email"] || "unknown"}). Check for a typo in the Category column, or set DEFAULT_CATEGORY above.`,
    );
  }

  let message = templatesForCategory[stage];
  if (!message) {
    throw new Error(
      `No follow-up content found for stage ${stage} under Category "${rawCategory}" (row: ${d["Email"] || "unknown"}).`,
    );
  }

  message = message
    .replace(/{{Name}}/g, d["Name"] || "")
    .replace(/{{Company}}/g, d["Company"] || "")
    .replace(/{{City}}/g, d["City"] || "");

  results.push({ json: { ...d, message }, pairedItem: item.pairedItem });
}

return results;
